-- marketplace: the Indian lead portals as real listings (docs/specs/lead-portals-feasibility.md, sections (a), (b), (e)).
-- Why this migration exists: the starting catalogue (20261021090300_mkt_seed.sql) kept the planned portals as DRAFT listings with no recipe, so
-- the build order was on record and no workspace saw something that did not work. The connector framework now does: a pull connector with
-- time windows, a signed request, the portal's own limits and penalties, and a push door that stores every delivery before it answers
-- (20261024090000_mkt_portal_engine.sql). This turns each draft into a published listing with its recipe, STRICTLY as far as the research
-- supports it:
--   IndiaMART  push (real time) AND pull (every 15 minutes), documented by IndiaMART itself        -> stable
--   Housing.com pull, HMAC signed, no lead id (a derived key), documented by Housing.com           -> needs portal setup (they issue the key)
--   TradeIndia pull ("My Inquiry API"), partly documented                                          -> beta
--   JustDial, 99acres, MagicBricks, Shiksha, Sulekha  push, set up by the PORTAL's team, payload shape only PROPOSED -> needs portal setup
-- Not here, on purpose: Collegedunia, NoBroker, Quikr, CarDekho (no mechanism found), Naukri (candidate ATS, not leads), and email-alert
-- parsing (the Email channel does not exist yet). No recipe stores a portal username or password.
--
-- Idempotent and non-destructive: a portal is published ONLY while its listing is still an untouched draft (never published, no current
-- version), so re-running it, or running it after an operator edited, hid or killed a listing, changes nothing. Every manifest, recipe and
-- listing below is validated against the contracts by test/unit/marketplace/portal-recipes.spec.ts, which reads this file, and every sample
-- payload is run through its recipe's mapping there.

SELECT set_config('app.privileged', 'on', true);

-- The two portals that had no draft yet.
WITH planned (slug, name, tagline, connector) AS (
  VALUES
    ('sulekha', 'Sulekha', 'Bring Sulekha enquiries into your workspace as leads.', 'push'),
    ('tradeindia', 'TradeIndia', 'Bring TradeIndia inquiries into your workspace as leads.', 'pull')
)
INSERT INTO marketplace_apps (slug, kind, category_id, name, tagline, status, first_party, connector_type, sort_order)
SELECT p.slug, 'integration', c.id, p.name, p.tagline, 'draft', true, p.connector, 200
FROM planned p CROSS JOIN marketplace_categories c
WHERE c.kind = 'integration' AND c.slug = 'lead-sources'
ON CONFLICT (slug) DO NOTHING;

CREATE TEMP TABLE _mkt_portal_seed (
  slug text PRIMARY KEY, connector text NOT NULL, sort_order integer NOT NULL, featured boolean NOT NULL, tagline text NOT NULL,
  manifest jsonb NOT NULL, recipe jsonb NOT NULL, listing jsonb NOT NULL, changelog text NOT NULL
) ON COMMIT DROP;

INSERT INTO _mkt_portal_seed (slug, connector, sort_order, featured, tagline, manifest, recipe, listing, changelog) VALUES
  ('indiamart', 'pull', 10, true, 'Bring IndiaMART buyer enquiries into your workspace as leads, in real time.',
   $j${"manifestVersion":1,"id":"indiamart","name":"IndiaMART","kind":"integration","category":"lead-sources","version":"1.0.0","description":"Receive IndiaMART buyer enquiries as leads in real time through IndiaMART's Push API, and fill any gap by reading your IndiaMART leads every 15 minutes with your CRM key.","scopes":["leads.write"],"surfaces":[{"type":"webhook_in","key":"leads","label":"Incoming leads"}],"pricing":{"model":"free"},"support":{"website":"https://www.indiamart.com","docs":"https://help.indiamart.com/knowledge-base/lms-crm-integration-v2"},"connector":{"type":"pull"}}$j$::jsonb,
   $j${"schemaVersion":1,"key":"indiamart","name":"IndiaMART","category":"lead-sources","logo":null,"connector":{"type":"pull","request":{"method":"GET","baseUrl":"https://mapi.indiamart.com","path":"/wservce/crm/crmListing/v2/","query":{"glusr_crm_key":"{{cred.crmKey}}","start_time":"{{window_start}}","end_time":"{{window_end}}"},"headers":{}},"response":{"itemsPath":"RESPONSE","statusPath":"CODE","emptyStatuses":[204]},"window":{"format":"DD-MM-YYYYHH:mm:ss","utcOffsetMinutes":330,"maxSeconds":518400,"overlapSeconds":1800,"initialLookbackSeconds":86400,"maxLookbackSeconds":31536000},"pollIntervalSeconds":900,"limits":{"minIntervalSeconds":300,"requestsPerMinute":5},"maxItemsPerPoll":2000,"push":{"delivery":{"methods":["POST"],"formats":["json"],"mode":"async"}}},"authFields":[{"key":"crmKey","label":"CRM key","kind":"secret","required":true,"help":"In IndiaMART open Lead Manager, then the CRM API page (seller.indiamart.com/leadmanager/crmapi) and generate the key. Generating a new key later stops the old one.","placeholder":"Paste the key from IndiaMART"}],"mapping":{"mode":"explicit","itemsPath":"RESPONSE","externalId":{"from":"UNIQUE_QUERY_ID"},"receivedAt":{"from":"QUERY_TIME","format":"iso","utcOffsetMinutes":330},"defaultCountryCode":"91","fields":[{"to":"name","from":"SENDER_NAME","ignore":["IndiaMART Buyer"]},{"to":"phone","from":"SENDER_MOBILE","fallbackFrom":["SENDER_MOBILE_ALT","SENDER_PHONE","SENDER_PHONE_ALT"],"transform":["phone"]},{"to":"email","from":"SENDER_EMAIL","fallbackFrom":["SENDER_EMAIL_ALT"],"transform":["trim","lower"]},{"to":"message","from":"QUERY_MESSAGE","transform":["unescape"]},{"to":"subject","from":"SUBJECT"},{"to":"company","from":"SENDER_COMPANY"},{"to":"address","from":"SENDER_ADDRESS"},{"to":"city","from":"SENDER_CITY"},{"to":"state","from":"SENDER_STATE"},{"to":"pincode","from":"SENDER_PINCODE"},{"to":"country","from":"SENDER_COUNTRY_ISO"},{"to":"product","from":"QUERY_PRODUCT_NAME","fallbackFrom":["QUERY_MCAT_NAME"]},{"to":"category","from":"QUERY_MCAT_NAME"},{"to":"lead_type","from":"QUERY_TYPE","map":{"W":"Direct enquiry","B":"Buy lead","P":"Call (PNS)","BIZ":"Catalog view","WA":"WhatsApp"}},{"to":"call_duration","from":"CALL_DURATION"},{"to":"receiver_mobile","from":"RECEIVER_MOBILE"}],"attribution":{"platform":{"const":"indiamart"},"campaign":{"from":"QUERY_TYPE","map":{"W":"Direct enquiry","B":"Buy lead","P":"Call (PNS)","BIZ":"Catalog view","WA":"WhatsApp"}},"form":{"from":"QUERY_MCAT_NAME"}}},"rateLimits":{"perMinute":300},"errorMapping":[{"status":429,"bodyContains":"Too Many Requests","code":"key_blocked","message":"IndiaMART blocked the CRM key for 15 minutes because it was used too often. The connection tries again after that.","retry":true,"health":"degraded","retryAfterSeconds":900},{"status":429,"code":"rate_limited","message":"IndiaMART asked us to wait: its CRM key may be used once every 5 minutes.","retry":true,"health":"degraded","retryAfterSeconds":300},{"status":401,"bodyContains":"expired","code":"key_expired","message":"The IndiaMART CRM key expired because it was not used for 7 days. Generate a new key in IndiaMART and enter it here.","retry":false,"health":"needs_reauth"},{"status":401,"code":"key_rejected","message":"IndiaMART refused the CRM key. If you generated a new key in IndiaMART the old one stopped working: enter the new key here.","retry":false,"health":"needs_reauth"},{"status":400,"code":"request_refused","message":"IndiaMART did not accept the request (the dates it was asked for). Tell support.","retry":false,"health":"error"},{"statusRange":[500,599],"code":"portal_error","message":"IndiaMART had a problem answering. The connection tries again.","retry":true,"health":"degraded"}],"setupInstructions":[{"title":"Generate your IndiaMART CRM key","body":"Sign in to IndiaMART, open Lead Manager and go to the CRM API page (seller.indiamart.com/leadmanager/crmapi). Press Generate Key, copy the key and paste it in the CRM key field above. The leads API is an add-on to your IndiaMART plan: if you cannot generate a key, ask your IndiaMART account representative to switch it on. Careful: generating a new key later stops this one, and a key that is not used for 7 days expires."},{"title":"We read your leads every 15 minutes","body":"Once the key is saved we ask IndiaMART for your new leads about every 15 minutes (IndiaMART allows one request every 5 minutes) and never miss one between two reads. Press Sync now to read sooner. Leads from before you connected are not imported, only the last day."},{"title":"Turn on real-time delivery (recommended)","body":"After you install, a private web address is shown once. In IndiaMART open Lead Manager, then Import/Export Leads, then Push API, choose Other, paste the address and confirm with the OTP IndiaMART sends to your registered mobile number. IndiaMART then sends each enquiry the moment it arrives. Copy the address when it is shown: it is not shown again (you can create a new one at any time)."},{"title":"IndiaMART turns Push off after 48 hours of failures","body":"If the address does not accept leads for 48 hours in a row, IndiaMART deactivates the Push API and you must switch it on again in Lead Manager. We always answer IndiaMART at once and keep a copy of each delivery, so this only happens when the address was pasted wrongly or this connection stays paused for two days. Keep the 15-minute reading on while Push is paused."},{"title":"Check it with a sample lead","body":"Press Send sample lead to see how an IndiaMART enquiry becomes a lead here. Real enquiries arrive with the buyer's name, mobile, email, message, city, product and the kind of enquiry (direct, buy lead, call, catalog or WhatsApp)."}],"testPayloads":[{"name":"Direct enquiry","payload":{"CODE":200,"STATUS":"SUCCESS","RESPONSE":{"UNIQUE_QUERY_ID":"2000000001","QUERY_TYPE":"W","QUERY_TIME":"2026-10-04 11:17:14","SENDER_NAME":"Rohit Sharma","SENDER_MOBILE":"+91-9876543210","SENDER_EMAIL":"Rohit.Sharma@example.com","SUBJECT":"Requirement for Stainless Steel Pipes","SENDER_COMPANY":"Sharma Fabricators","SENDER_ADDRESS":"Plot 12, MIDC Bhosari","SENDER_CITY":"Pune","SENDER_STATE":"Maharashtra","SENDER_PINCODE":"411026","SENDER_COUNTRY_ISO":"IN","QUERY_PRODUCT_NAME":"Stainless Steel Pipes","QUERY_MCAT_NAME":"Steel Pipes","QUERY_MESSAGE":"I need 500 pieces of 2 inch pipe.\\nPlease send your best price."}}},{"name":"Buyer with no name (call)","payload":{"CODE":200,"STATUS":"SUCCESS","RESPONSE":{"UNIQUE_QUERY_ID":"2000000002","QUERY_TYPE":"P","QUERY_TIME":"2026-10-04 12:01:40","SENDER_NAME":"IndiaMART Buyer","SENDER_MOBILE":"+91-9123456780","SENDER_COUNTRY_ISO":"IN","CALL_DURATION":"48","RECEIVER_MOBILE":"+91-9000000000"}}}]}$j$::jsonb,
   $j${"maturity":"stable","notice":"Needs the leads API add-on on your IndiaMART plan. You switch on real-time delivery yourself in IndiaMART Lead Manager; IndiaMART turns it off after 48 hours of failed deliveries.","longDescription":"Connect your IndiaMART seller account and every buyer enquiry becomes a lead in your workspace, with the buyer's name, mobile, email, company, city, product and message.\n\nTwo doors are used together. IndiaMART's Push API sends each enquiry the moment it arrives, and a scheduled read with your CRM key (every 15 minutes) fills any gap, so a lead is not lost if one door is down. A lead that arrives by both is added once.\n\nThe connection follows IndiaMART's published rules: no request more often than once in 5 minutes, windows of at most 7 days, and a pause of 15 minutes if IndiaMART asks us to slow down.","highlights":["Real-time delivery through IndiaMART's Push API","A scheduled catch-up every 15 minutes with your CRM key, so nothing is missed","The same lead from both doors is added once","A visible health state, the time of the last read, and a Sync now button"],"screenshots":[],"dataProcessing":{"summary":"Each lead is passed to your workspace's lead pipeline and stored there with your other leads. The platform keeps a record of each delivery (an id and a status) for 30 days so you can see recent activity, and a copy of the delivery itself only until it has been processed (up to 30 days if it could not be read). Your IndiaMART CRM key is stored sealed and is never shown again.","regions":[],"deletion":"Uninstalling removes the connection, its private address and any stored key at once. Leads that already arrived stay in your workspace until you delete them."}}$j$::jsonb,
   'First release: IndiaMART Push API (real time) and CRM key polling.'),
  ('justdial', 'push', 20, false, 'Bring JustDial enquiries into your workspace as leads.',
   $j${"manifestVersion":1,"id":"justdial","name":"JustDial","kind":"integration","category":"lead-sources","version":"1.0.0","description":"Receive JustDial leads at a private address that your JustDial account manager points JustDial's sender at. JustDial delivers with GET and a query string; the lead is added as soon as it arrives.","scopes":["leads.write"],"surfaces":[{"type":"webhook_in","key":"leads","label":"Incoming leads"}],"pricing":{"model":"free"},"support":{"website":"https://www.justdial.com"},"connector":{"type":"push"}}$j$::jsonb,
   $j${"schemaVersion":1,"key":"justdial","name":"JustDial","category":"lead-sources","logo":null,"connector":{"type":"push","auth":{"scheme":"path_token"},"delivery":{"methods":["GET","POST"],"formats":["query","form","json"],"mode":"async"}},"authFields":[],"mapping":{"mode":"auto","platform":"justdial","defaultCountryCode":"91","receivedAtApproximate":true,"utcOffsetMinutes":330},"rateLimits":{"perMinute":300},"errorMapping":[],"setupInstructions":[{"title":"Install, then copy the private address","body":"After you install, a private web address is shown once. Copy it now: it is also the connection's password. You can create a new one at any time if you lose it (the old one then stops working)."},{"title":"Ask your JustDial account manager to add the address","body":"Email your JustDial account manager (or their backend team) and ask them to deliver your leads to the private address, using the GET method. Ask for a sample lead and a test lead so you can see it arrive. Until JustDial adds it, no leads come in. This step is theirs, not ours, and can take some days."},{"title":"About the time of a lead","body":"We found no time field in what JustDial sends, so each lead is dated with the moment we received it. If JustDial also emails you each lead, that email is not read: reading alert emails is not available yet."},{"title":"Send a sample so the field mapping can be checked","body":"JustDial has not published the fields it sends, so the usual names (name, mobile or phone, email, message, city) are read and everything else is kept as it came. Ask JustDial for a sample or test lead, and send it to us if a field is missing or lands in the wrong place: the mapping is adjusted from a real example. Press Send sample lead to see how a typical lead looks here."}],"testPayloads":[{"name":"Sample lead (proposed fields)","payload":{"leadid":"JD-SAMPLE-1","name":"Meera Nair","mobile":"9876543210","email":"Meera.Nair@example.com","company":"Sample Interiors","category":"Interior Designers","city":"Kochi","brancharea":"Edappally","pincode":"682024"}}]}$j$::jsonb,
   $j${"maturity":"needs_portal_setup","notice":"JustDial's own team switches this on, not you: after installing, send the private address to your JustDial account manager and ask for GET delivery. Field names are proposed until a real lead arrives.","longDescription":"JustDial has no setting you can change yourself. Instead you give your JustDial account manager a private address, and their team makes JustDial send each of your leads there. This listing gives you that address, checks every delivery, and turns it into a lead with the caller's name, mobile, email, category and city.\n\nIt works with the GET delivery JustDial's sender uses, and also accepts a POST. Nothing arrives until JustDial's team has added the address, so the connection page shows \"waiting for the first lead\" until then.","highlights":["Leads from JustDial arrive as soon as JustDial sends them","A repeat of the same lead is recognised, never added twice","Every delivery is stored first, so a busy moment never loses a lead","We never ask for your portal login"],"screenshots":[],"dataProcessing":{"summary":"Each lead is passed to your workspace's lead pipeline and stored there with your other leads. The platform keeps a record of each delivery (an id and a status) for 30 days so you can see recent activity, and a copy of the delivery itself only until it has been processed (up to 30 days if it could not be read).","regions":[],"deletion":"Uninstalling removes the connection, its private address and any stored key at once. Leads that already arrived stay in your workspace until you delete them."}}$j$::jsonb,
   'First release: a private address JustDial''s team points its sender at (set up by JustDial, field names proposed).'),
  ('acres99', 'push', 30, false, 'Bring 99acres property enquiries into your workspace as leads.',
   $j${"manifestVersion":1,"id":"acres99","name":"99acres","kind":"integration","category":"lead-sources","version":"1.0.0","description":"Receive 99acres property enquiries at a private address that your 99acres account manager points 99acres's sender at. We never ask for your 99acres username or password.","scopes":["leads.write"],"surfaces":[{"type":"webhook_in","key":"leads","label":"Incoming leads"}],"pricing":{"model":"free"},"support":{"website":"https://www.99acres.com"},"connector":{"type":"push"}}$j$::jsonb,
   $j${"schemaVersion":1,"key":"acres99","name":"99acres","category":"lead-sources","logo":null,"connector":{"type":"push","auth":{"scheme":"path_token"},"delivery":{"methods":["POST"],"formats":["json","form","xml"],"mode":"async"}},"authFields":[],"mapping":{"mode":"auto","platform":"99acres","defaultCountryCode":"91","receivedAtApproximate":true,"utcOffsetMinutes":330},"rateLimits":{"perMinute":300},"errorMapping":[],"setupInstructions":[{"title":"Install, then copy the private address","body":"After you install, a private web address is shown once. Copy it now: it is also the connection's password. You can create a new one at any time if you lose it (the old one then stops working)."},{"title":"Ask your 99acres account manager to add the address","body":"Email your 99acres account manager and ask them to deliver your leads to the private address. They will ask which of your projects to include (their names and 99acres ids): have them ready. Until 99acres adds the address no leads come in. This step is theirs, not ours."},{"title":"We never need your 99acres login","body":"Some CRMs read 99acres by storing your username and password. We do not, and will not: if 99acres only offers that, ask them for a keyed API instead."},{"title":"Send a sample so the field mapping can be checked","body":"99acres has not published the fields it sends, so the usual names (name, mobile or phone, email, message, city) are read and everything else is kept as it came. Ask 99acres for a sample or test lead, and send it to us if a field is missing or lands in the wrong place: the mapping is adjusted from a real example. Press Send sample lead to see how a typical lead looks here."}],"testPayloads":[{"name":"Sample lead (proposed fields)","payload":{"name":"Karan Mehta","email":"Karan.Mehta@example.com","phone":"9876543210","country_code":"91","project_name":"Sample Residency","project_id":"P-1001","city":"Gurugram","locality":"Sector 56","remarks":"Looking for a 3 BHK, please call"}}]}$j$::jsonb,
   $j${"maturity":"needs_portal_setup","notice":"99acres's own team switches this on, not you: after installing, send the private address to your 99acres account manager. Field names are proposed until a real lead arrives.","longDescription":"99acres does not publish how it delivers leads. In practice your 99acres account manager adds your CRM's address on 99acres's side. This listing gives you that private address and turns every delivery (JSON, a form or an XML document) into a lead with the buyer's name, phone, email, project and message.\n\nWe never ask for your 99acres username or password.","highlights":["Leads from 99acres arrive as soon as 99acres sends them","A repeat of the same lead is recognised, never added twice","Every delivery is stored first, so a busy moment never loses a lead","We never ask for your portal login"],"screenshots":[],"dataProcessing":{"summary":"Each lead is passed to your workspace's lead pipeline and stored there with your other leads. The platform keeps a record of each delivery (an id and a status) for 30 days so you can see recent activity, and a copy of the delivery itself only until it has been processed (up to 30 days if it could not be read).","regions":[],"deletion":"Uninstalling removes the connection, its private address and any stored key at once. Leads that already arrived stay in your workspace until you delete them."}}$j$::jsonb,
