   $j${"schemaVersion":1,"key":"magicbricks","name":"MagicBricks","category":"lead-sources","logo":null,"connector":{"type":"push","auth":{"scheme":"path_token"},"delivery":{"methods":["POST","GET"],"formats":["json","form","query"],"mode":"async"}},"authFields":[],"mapping":{"mode":"auto","platform":"magicbricks","defaultCountryCode":"91","receivedAtApproximate":true,"utcOffsetMinutes":330},"rateLimits":{"perMinute":300},"errorMapping":[],"setupInstructions":[{"title":"Install, then copy the private address","body":"After you install, a private web address is shown once. Copy it now: it is also the connection's password. You can create a new one at any time if you lose it (the old one then stops working)."},{"title":"Ask your MagicBricks account manager to add the address","body":"Email your MagicBricks account manager with the private address, your MagicBricks Login ID, and say you want a PUSH integration to a CRM. Until they add it no leads come in. This step is theirs, not ours."},{"title":"Send a sample so the field mapping can be checked","body":"MagicBricks has not published the fields it sends, so the usual names (name, mobile or phone, email, message, city) are read and everything else is kept as it came. Ask MagicBricks for a sample or test lead, and send it to us if a field is missing or lands in the wrong place: the mapping is adjusted from a real example. Press Send sample lead to see how a typical lead looks here."}],"testPayloads":[{"name":"Sample lead (proposed fields)","payload":{"name":"Sneha Iyer","mobile":"9876543210","email":"Sneha.Iyer@example.com","remark":"Interested in this flat, please call back","project":"Sample Towers","pid":"MB-5001","source":"magicbricks","responsetype":"lead","account":"owner@example.com"}}]}$j$::jsonb,
   $j${"maturity":"needs_portal_setup","notice":"MagicBricks's own team switches this on, not you: after installing, send the private address and your MagicBricks Login ID to your account manager. Field names are proposed until a real lead arrives.","longDescription":"MagicBricks does not publish how it delivers leads: your account manager configures a sender for each CRM. This listing gives you the private address to give them, and turns every delivery into a lead with the buyer's name, mobile, email, project and remark.","highlights":["Leads from MagicBricks arrive as soon as MagicBricks sends them","A repeat of the same lead is recognised, never added twice","Every delivery is stored first, so a busy moment never loses a lead","We never ask for your portal login"],"screenshots":[],"dataProcessing":{"summary":"Each lead is passed to your workspace's lead pipeline and stored there with your other leads. The platform keeps a record of each delivery (an id and a status) for 30 days so you can see recent activity, and a copy of the delivery itself only until it has been processed (up to 30 days if it could not be read).","regions":[],"deletion":"Uninstalling removes the connection, its private address and any stored key at once. Leads that already arrived stay in your workspace until you delete them."}}$j$::jsonb,
