  ('housing-com', 'pull', 50, false, 'Bring Housing.com property enquiries into your workspace as leads.',
   $j${"manifestVersion":1,"id":"housing-com","name":"Housing.com","kind":"integration","category":"lead-sources","version":"1.0.0","description":"Read your Housing.com builder leads every 30 minutes with the ID and secret key Housing.com gives you, and add each one as a lead without duplicates.","scopes":["leads.write"],"surfaces":[],"pricing":{"model":"free"},"support":{"website":"https://housing.com"},"connector":{"type":"pull"}}$j$::jsonb,
   $j${"schemaVersion":1,"key":"housing-com","name":"Housing.com","category":"lead-sources","logo":null,"connector":{"type":"pull","request":{"method":"GET","baseUrl":"https://leads.housing.com","path":"/api/v0/get-builder-leads","query":{"id":"{{cred.housingId}}","start_date":"{{window_start}}","end_date":"{{window_end}}"},"headers":{},"sign":{"algorithm":"hmac_sha256","keyField":"secretKey","timestampParam":"current_time","signatureParam":"hash"}},"response":{},"window":{"format":"epoch","utcOffsetMinutes":0,"maxSeconds":604800,"overlapSeconds":1800,"initialLookbackSeconds":86400,"maxLookbackSeconds":31536000},"pollIntervalSeconds":1800,"limits":{"minIntervalSeconds":300,"requestsPerMinute":6},"maxItemsPerPoll":2000},"authFields":[{"key":"housingId","label":"Housing.com ID","kind":"text","required":true,"help":"The unique ID Housing.com gave your account. It is not secret.","placeholder":"For example 4544"},{"key":"secretKey","label":"Secret key","kind":"secret","required":true,"help":"The secret key Housing.com gave you. Never share it."}],"mapping":{"mode":"explicit","defaultCountryCode":"91","externalIdDerive":{"parts":[{"from":"lead_phone","transform":["phone"]},{"from":"project_id"},{"from":"lead_date"}],"prefix":"hs"},"receivedAt":{"from":"lead_date","format":"epoch_seconds"},"fields":[{"to":"name","from":"lead_name"},{"to":"phone","from":"lead_phone","transform":["phone"]},{"to":"email","from":"lead_email","transform":["trim","lower"]},{"to":"product","from":"project_name"},{"to":"project_id","from":"project_id"},{"to":"locality","from":"locality"}],"attribution":{"platform":{"const":"housing"},"form":{"from":"project_id"}}},"rateLimits":{"perMinute":120},"errorMapping":[{"status":401,"code":"auth_rejected","message":"Housing.com refused the request: check the ID and the secret key, and that this server's clock is within 15 minutes of the real time.","retry":false,"health":"needs_reauth"},{"status":422,"code":"request_refused","message":"Housing.com did not accept the request (a missing or badly written parameter). Tell support.","retry":false,"health":"error"},{"statusRange":[500,599],"code":"portal_error","message":"Housing.com had a problem answering. The connection tries again.","retry":true,"health":"degraded"}],"setupInstructions":[{"title":"Ask Housing.com for your ID and secret key","body":"Housing.com gives each builder account an ID and a secret key when it registers you for lead delivery. Ask your Housing.com account manager for them (the paper they work from is called the Developer's CRM Integration Document). Enter the ID and the secret key above. The key is stored sealed and never shown again."},{"title":"How we read your leads","body":"About every 30 minutes we ask Housing.com for your new leads, signing each request with your key. Housing.com gives leads no number of their own, so we recognise a lead by the buyer's phone, the project and the time Housing.com recorded: the same lead is never added twice. Press Sync now to read sooner."},{"title":"Check the first read","body":"Press Test connection once the keys are saved. If Housing.com refuses the request, check the ID and the key. A request is also refused when the clock of the server is more than 15 minutes off: tell support if you see that. Housing.com sends the buyer's name, phone, email and the project, but no message."},{"title":"About the locality","body":"The locality Housing.com sends is the locality of the project, not the buyer's city, so it is kept as a separate field and the city is left empty."}],"testPayloads":[{"name":"Two leads","payload":[{"lead_name":"Anita Rao","lead_phone":"9876543210","lead_email":"Anita.Rao@example.com","project_id":1233,"project_name":"Sample Heights","locality":"Powai","lead_date":"1759576634"},{"lead_name":"Vikram Shah","lead_phone":"9123456780","lead_email":null,"project_id":1233,"project_name":"Sample Heights","locality":"Powai","lead_date":"1759580234"}]}]}$j$::jsonb,
   $j${"maturity":"needs_portal_setup","notice":"Housing.com issues the ID and secret key: ask your Housing.com account manager. Its integration document is an older copy and states no rate limit, so watch the first reads.","longDescription":"Connect your Housing.com builder account and each property enquiry becomes a lead in your workspace, with the buyer's name, phone, email and the project they asked about.\n\nHousing.com is read on a schedule (about every 30 minutes) with the ID and secret key Housing.com gives you; every request is signed as Housing.com requires. Housing.com does not number its leads, so the connection recognises the same lead by the buyer, the project and the time, and never adds it twice.","highlights":["Signed requests, as Housing.com's own integration document describes","No duplicates, although Housing.com gives leads no number","Reads about every 30 minutes, with a Sync now button","Your secret key is stored sealed and never shown again"],"screenshots":[],"dataProcessing":{"summary":"Each lead is passed to your workspace's lead pipeline and stored there with your other leads. The platform keeps a record of each delivery (an id and a status) for 30 days so you can see recent activity, and a copy of the delivery itself only until it has been processed (up to 30 days if it could not be read). Your Housing.com secret key is stored sealed and is never shown again.","regions":[],"deletion":"Uninstalling removes the connection, its private address and any stored key at once. Leads that already arrived stay in your workspace until you delete them."}}$j$::jsonb,
   'First release: signed polling of the Housing.com builder leads API.'),
