-- Version 1.0.0, published, for each portal whose listing is still an untouched draft.
INSERT INTO marketplace_app_versions (app_id, version, status, manifest, recipe, scopes, changelog, published_at, reviewed_at)
SELECT a.id, '1.0.0', 'published', s.manifest, s.recipe, ARRAY['leads.write']::text[], s.changelog, now(), now()
FROM _mkt_portal_seed s JOIN marketplace_apps a ON a.slug = s.slug
WHERE a.status = 'draft' AND a.current_version_id IS NULL
ON CONFLICT (app_id, version) DO NOTHING;

-- The planning stub of the first migration is superseded.
UPDATE marketplace_app_versions v SET status = 'retired'
FROM marketplace_apps a
WHERE v.app_id = a.id AND v.version = '0.1.0' AND v.status = 'draft'
  AND a.slug IN (SELECT slug FROM _mkt_portal_seed)
  AND a.status = 'draft' AND a.current_version_id IS NULL
  AND EXISTS (SELECT 1 FROM marketplace_app_versions w WHERE w.app_id = a.id AND w.version = '1.0.0' AND w.status = 'published');

-- Publish.
UPDATE marketplace_apps a SET
  status = 'published', current_version_id = v.id, published_at = now(), connector_type = s.connector,
  tagline = s.tagline, listing = s.listing, sort_order = s.sort_order, featured = s.featured
FROM _mkt_portal_seed s, marketplace_app_versions v
WHERE a.slug = s.slug AND v.app_id = a.id AND v.version = '1.0.0' AND v.status = 'published'
  AND a.status = 'draft' AND a.current_version_id IS NULL;
